add("gseb2024_48", ("(a) मानव पाचन तंत्र में pH का महत्व समझाइए।\n\n(b) समझाइए कि pH में परिवर्तन से दंत-क्षय कैसे होता है।", "(a) માનવ પાચનતંત્રમાં pH નું મહત્ત્વ સમજાવો.\n\n(b) pH માં ફેરફારથી દાંતનો સડો કેવી રીતે થાય છે તે સમજાવો."),
    {0: ("(a) आमाशय पाचन के लिए हाइड्रोक्लोरिक अम्ल बनाता है। अम्ल की अधिकता से दर्द और जलन (अपच) होती है; मिल्क ऑफ़ मैग्नीशिया जैसा प्रति-अम्ल अतिरिक्त अम्ल को उदासीन करता है।",
         "(a) જઠર પાચન માટે હાઇડ્રોક્લોરિક ઍસિડ બનાવે છે. ઍસિડની વધુ માત્રાથી દુખાવો અને બળતરા (અપચો) થાય છે; મિલ્ક ઑફ મૅગ્નેશિયા જેવો ઍન્ટાસિડ વધારાના ઍસિડને તટસ્થ કરે છે."),
     1: ("(b) मुँह के बैक्टीरिया खाने के बाद बची शर्करा और भोजन से अम्ल बनाते हैं। जब pH 5.5 से कम होता है, तो दाँतों का इनैमल (कैल्सियम हाइड्रॉक्सीऐपेटाइट) संक्षारित होने लगता है।",
         "(b) મોંના બૅક્ટેરિયા જમ્યા પછી રહી ગયેલી શર્કરા અને ખોરાકમાંથી ઍસિડ બનાવે છે. જ્યારે pH 5.5 કરતાં ઓછો થાય, ત્યારે દાંતનું ઇનેમલ (કૅલ્શિયમ હાઇડ્રૉક્સીએપેટાઇટ) ખવાવા લાગે છે."),
     2: ("क्षारकीय टूथपेस्ट से ब्रश करने पर अम्ल उदासीन हो जाता है और क्षय रुकता है।", "બેઝિક ટૂથપેસ્ટથી બ્રશ કરતાં ઍસિડ તટસ્થ થાય છે અને સડો અટકે છે.")})
add("gseb2025_48", ("प्लास्टर ऑफ़ पेरिस कैसे बनता है? प्लास्टर ऑफ़ पेरिस और जल के बीच अभिक्रिया दर्शाने वाला समीकरण लिखिए। प्लास्टर ऑफ़ पेरिस के उपयोग लिखिए।", "પ્લાસ્ટર ઑફ પૅરિસ કેવી રીતે બને છે? પ્લાસ્ટર ઑફ પૅરિસ અને પાણી વચ્ચેની પ્રક્રિયા દર્શાવતું સમીકરણ લખો. પ્લાસ્ટર ઑફ પૅરિસના ઉપયોગ લખો."),
    {0: ("जिप्सम को 373 K पर गर्म किया जाता है: {0}", "જિપ્સમને 373 K એ ગરમ કરવામાં આવે છે: {0}"), 1: ("जल के साथ: {0}", "પાણી સાથે: {0}"),
     2: ("उपयोग: टूटी हड्डियों को सहारा देने वाला प्लास्टर, खिलौने और सजावटी सामान बनाना, और सतहों को चिकना करना।", "ઉપયોગ: ભાંગેલાં હાડકાંને ટેકો આપતું પ્લાસ્ટર, રમકડાં અને શણગારની વસ્તુઓ બનાવવી, અને સપાટી લીસી કરવી.")})
